  // Learner activity records go to the page around this one when there is one (the StudyDesk learner page passes them on to the analytics); on its own a page like this sends nothing anywhere
  // Variables the project lists as outputs go to the parent page too (a project with no public interface sends none)
  var outputs = player.describe().variables.filter(function (v) { return v.direction !== 'input'; }).map(function (v) { return v.name; });
  if (outputs.length) player.on('variablechange', function (c) { if (outputs.indexOf(c.name) >= 0 && window.parent !== window) window.parent.postMessage({ source: 'interactives-variable', name: c.name, value: c.value }, '*'); });
  player.on('record', function (r) { if (window.parent !== window) window.parent.postMessage({ source: 'interactives-record', record: r }, '*'); });
